eventScript.func:
const INVOICE_RULE_FIELD = 'reload_invoice_no_type';

// Locked once the document exists. Edit mode exists only to settle payment
// (Unpaid -> Paid), so everything that defines the document itself is frozen.
const LOCKED_ON_EDIT = [
  'reload_invoice_no',
  'reload_invoice_no_type',
  'reload_date',
  'tenant_2',
  'reload_type',
  'currency_id',
  'exchange_rate',
  'reload_amount',
  'reload_discount',
  'reload_discount_uom',
];

const PAYMENT_FIELDS = [
  'payment_status',
  'payment_term',
  'payment_method',
  'payment_date',
];

// Local calendar date. Deliberately not toISOString(), which is UTC and would
// hand back yesterday for a UTC+8 user working between midnight and 08:00.
const todayLocal = () => {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
};

// The invoice-number rule dropdown populates asynchronously - poll until the
// component reports its options, then apply the default rule.
const setupInvoiceRule = async () => {
  const maxRetries = 10;
  const interval = 500;

  for (let i = 0; i < maxRetries; i++) {
    const op = await this.onDropdownVisible(INVOICE_RULE_FIELD, true);
    if (op != null) break;
    await new Promise((resolve) => setTimeout(resolve, interval));
  }

  const getDefaultItem = (arr) => arr?.find((item) => item?.item?.is_default === 1);

  const params = this.getComponent('reload_invoice_no');
  const { options } = params;

  const optionsData = this.getOptionData(INVOICE_RULE_FIELD) || [];
  const defaultData = getDefaultItem(optionsData);

  if (options?.canManualInput) {
    this.setOptionData(INVOICE_RULE_FIELD, [
      { label: 'Manual Input', value: -9999 },
      ...optionsData,
    ]);

    if (this.isAdd) {
      this.setData({
        [INVOICE_RULE_FIELD]: defaultData ? defaultData.value : -9999,
      });
    }
  } else if (defaultData && this.isAdd) {
    this.setData({ [INVOICE_RULE_FIELD]: defaultData.value });
  }
};

setTimeout(async () => {
  try {
    await setupInvoiceRule();

    // The save workflow branches on this - it must always be populated.
    const pageStatus = this.isAdd
      ? 'Add'
      : this.isEdit
        ? 'Edit'
        : this.isView
          ? 'View'
          : '';
    this.setData({ page_status: pageStatus });

    if (this.isAdd) {
      this.setData({ reload_date: todayLocal() });
      return;
    }

    if (this.isEdit) {
      this.disabled(LOCKED_ON_EDIT, true);
      this.disabled(PAYMENT_FIELDS, false);
      return;
    }

    if (this.isView) {
      this.disabled([...LOCKED_ON_EDIT, ...PAYMENT_FIELDS], true);
      this.hide(['button_save']);
    }
  } catch (error) {
    console.error('Credit Reload: onMounted failed', error);
  }
}, 200);

(async () => {
  try {
    const item = arguments[0]?.fieldModel?.item;
    if (!item) return;

    // Scalars come straight off the selected customer row - no fetch needed.
    this.setData({
      customer_name: item.customer_com_name || '',
      customer_reg_no: item.customer_com_reg_no || '',
      customer_tax_no: item.customer_tin_no || '',
      payment_term: item.customer_payment_term_id || null,
      monthly_remain_before: item.monthly_remain_credit || 0,
      flex_remain_before: item.flex_remain_credit || 0,
    });

    // --- billing address ---------------------------------------------------
    const addressList = item.address_list;

    if (Array.isArray(addressList) && addressList.length > 0) {
      const resBilling = await db
        .collection('address_purpose')
        .where({ purpose_name: 'Billing' })
        .get();

      // address_purpose is a global reference table - a missing row must not throw.
      const billingPurposeId = resBilling?.data?.[0]?.id;

      const billing =
        (billingPurposeId &&
          addressList.find(
            (address) =>
              address.address_purpose_id === billingPurposeId &&
              address.switch_save_as_default
          )) ||
        (billingPurposeId &&
          addressList.find(
            (address) => address.address_purpose_id === billingPurposeId
          )) ||
        addressList[0];

      if (billing) {
        // address_country_id / adddress_state are id-bound selects on this form
        // too, so the raw ids copy across without a name lookup.
        this.setData({
          address_name: billing.address_name || '',
          address_country_id: billing.address_country_id || null,
          adddress_state: billing.adddress_state || null,
          address_line_1: billing.address_line_1 || '',
          address_line_2: billing.address_line_2 || '',
          address_line_3: billing.address_line_3 || '',
          address_line_4: billing.address_line_4 || '',
          address_city: billing.address_city || '',
          address_postal_code: billing.address_postal_code || '',
          address_phone: billing.address_phone || '',
          address_phone2: billing.address_phone2 || '',
          address_mobile: billing.address_mobile || '',
          address_email: billing.address_email || '',
        });
      }
    } else {
      console.warn('Credit Reload: customer row carried no address_list', item);
    }

    // --- currency ----------------------------------------------------------
    // Re-set through '' so currency_id's onChange fires even when the new
    // customer happens to share the previous customer's currency.
    await this.setData({ currency_id: '' });
    await this.setData({ currency_id: item.customer_currency_id || null });
  } catch (error) {
    console.error('Credit Reload: failed to load customer', error);
    this.$message.error('Failed to load customer details.');
  }
})();

(async () => {
  const RATE_FIELDS = [
    'exchange_rate',
    'exchange_rate_myr',
    'exchange_rate_currency',
    'total_amount_myr',
  ];

  try {
    const currencyId = this.getValue('currency_id');

    if (!currencyId) {
      this.setData({ exchange_rate: 1, exchange_rate_currency: '', exchange_rate_myr: 'MYR' });
      this.hide(RATE_FIELDS);
      this.triggerEvent('func_recalc');
      return;
    }

    const resCurrency = await db.collection('currency').where({ id: currencyId }).get();
    const currencyEntry = resCurrency?.data?.[0];

    if (!currencyEntry) {
      console.warn('Credit Reload: currency not found', currencyId);
      this.triggerEvent('func_recalc');
      return;
    }

    const currencyCode = currencyEntry.currency_code;

    if (currencyCode && currencyCode !== 'MYR' && currencyCode !== '----') {
      // Foreign currency - the buying rate converts document currency into MYR.
      this.setData({
        exchange_rate: currencyEntry.currency_buying_rate || 1,
        exchange_rate_currency: currencyCode,
        exchange_rate_myr: 'MYR',
      });
      this.display(RATE_FIELDS);
    } else {
      // Already base currency - the MYR total would just duplicate total_amount.
      this.setData({
        exchange_rate: 1,
        exchange_rate_currency: currencyCode || '',
        exchange_rate_myr: 'MYR',
      });
      this.hide(RATE_FIELDS);
    }

    this.triggerEvent('func_recalc');
  } catch (error) {
    console.error('Credit Reload: failed to load currency', error);
    this.$message.error('Failed to load currency exchange rate.');
  }
})();

// Single source of truth for every computed amount on this form.
// Add On is priced off Flex Topup Rate; BASE_AMOUNT/BASE_CREDIT are the legacy
// Monthly Subscription package, still hardcoded until AI Credit Plan is wired up.
const BASE_AMOUNT = 45;
const BASE_CREDIT = 10000;
const TAX_RATE = 0.08;

// Every amount rounds DOWN, never up - 1.77779 lands on 1.7777, not 1.7778.
// Flooring the scaled value alone is not enough: 8.2 * 100 is 819.9999999999999
// in binary float and would truncate 8.20 down to 8.19. toPrecision(12) rubs out
// that representation noise while leaving a genuine 8.1999 untouched.
const roundDown = (value, dp) => {
  const factor = Math.pow(10, dp);
  const scaled = parseFloat(((parseFloat(value) || 0) * factor).toPrecision(12));
  return Math.floor(scaled) / factor;
};

const data = this.getValues();

const reloadAmount = parseFloat(data.reload_amount) || 0;
const exchangeRate = parseFloat(data.exchange_rate) || 1;
const reloadType = data.reload_type;
const subBefore = parseFloat(data.monthly_remain_before) || 0;
const reloadBefore = parseFloat(data.flex_remain_before) || 0;

// Credits scale linearly with the amount paid, and are read off the GROSS amount
// on purpose - a discount is a price concession, not a smaller top-up (same as
// SO, where so_discount never touches so_quantity). ai_credit_reload_amount is
// an int column (precision 0), and a part-credit is never granted.
//
// flex_topup_rate is MYR per credit, so an Add On crosses the exchange rate
// before dividing - a USD 45 reload must not buy the same credits as MYR 45.
// Monthly Subscription still prices off the raw document amount; that whole
// branch is replaced when AI Credit Plan lands.
// Parked in _data by onMounted / onChange_reload_type. Read, never fetched -
// this function runs on every keystroke in the amount field.
const flexRate = parseFloat(this.models?.['_data']?.flex_topup_rate) || 0;
const amountMyr = roundDown(reloadAmount * exchangeRate, 2);

// Named branches, not a default - an unrecognised type must grant nothing rather
// than quietly price as one of the two known ones.
let credits = 0;

if (reloadType === 'Add On') {
  // A missing rate previews as zero. The save workflow refuses the document
  // outright, so this can never be written as a real credit grant.
  if (flexRate > 0) {
    credits = roundDown(amountMyr / flexRate, 0);
  } else {
    console.warn('Credit Reload: Add On priced without a Flex Topup Rate');
  }
} else if (reloadType === 'Monthly Subscription') {
  credits = roundDown((reloadAmount / BASE_AMOUNT) * BASE_CREDIT, 0);
}

const totalGross = roundDown(reloadAmount, 2);

// Discount mirrors SOcalculation.js: a bare value defaults to Amount, and a
// value the gross cannot absorb is reset to zero rather than raising an error.
// The negative reset is an addition - total_discount is a positive-money column,
// so a negative would both inflate total_amount and be rejected on write.
let discount = parseFloat(data.reload_discount) || 0;
let discountUom = data.reload_discount_uom;
let discountAmount = 0;
let uomDefaulted = false;
let discountReset = false;

if (discount < 0) {
  discount = 0;
  discountReset = true;
}

// reload_discount is stored to 4 dp - truncate at the same precision the save
// workflow writes, so what is priced here is what ends up on the record.
discount = roundDown(discount, 4);

if (discount > 0 && !discountUom) {
  discountUom = 'Amount';
  uomDefaulted = true;
}

// Named branches, not a ternary with an Amount fallback - an unexpected type must
// price as nothing rather than quietly as an Amount.
if (discount > 0) {
  if (discountUom === '%') {
    discountAmount = roundDown((totalGross * discount) / 100, 2);
  } else if (discountUom === 'Amount') {
    discountAmount = roundDown(discount, 2);
  }
}

if (discountAmount > totalGross) {
  discount = 0;
  discountAmount = 0;
  discountReset = true;
}

// Tax is exclusive - added on top of the amount left after the discount.
const afterDiscount = roundDown(totalGross - discountAmount, 2);
const totalTax = roundDown(afterDiscount * TAX_RATE, 2);
const totalAmount = roundDown(afterDiscount + totalTax, 2);
const totalAmountMyr = roundDown(totalAmount * exchangeRate, 2);

// Monthly Subscription RESETS the subscription balance to the purchased credits,
// ignoring whatever was left. Add On accumulates onto the reload balance.
// Anything else leaves both balances untouched.
let subAfter = subBefore;
let reloadAfter = reloadBefore;

if (reloadType === 'Monthly Subscription') {
  subAfter = credits;
} else if (reloadType === 'Add On') {
  reloadAfter = reloadBefore + credits;
}

const updates = {
  ai_credit_reload_amount: credits,
  total_gross: totalGross,
  total_discount: discountAmount,
  total_tax_amount: totalTax,
  total_amount: totalAmount,
  total_amount_myr: totalAmountMyr,
  monthly_remain_after: subAfter,
  flex_remain_after: reloadAfter,
};

// The two entry fields are written back only when this function actually changed
// them - echoing every keystroke back into the inputs fights the caret.
if (uomDefaulted) {
  updates.reload_discount_uom = discountUom;
}

if (discountReset) {
  updates.reload_discount = 0;
}

this.setData(updates);

// Same workflow as Save - it answers a rate probe before any validation.
// Keep in step with SuduCreditReloadSave.js.
const CREDIT_RELOAD_SAVE_WORKFLOW_ID = '2079099954205609985';

// Add On is priced per credit off Flex Topup Rate, so there is no standard
// package to prefill - the user enters whatever they are paying. Monthly
// Subscription keeps the legacy package until AI Credit Plan is wired up; keep
// the 45 in step with BASE_AMOUNT in func_recalc.
(async () => {
  const reloadType = this.getValue('reload_type');

  if (reloadType !== 'Add On') {
    this.setData({ reload_amount: 45 });
    this.triggerEvent('func_recalc');
    return;
  }

  this.setData({ reload_amount: '' });

  // sudu_flex_topup sits in a different database, so the form cannot read it -
  // the save workflow resolves it through a probe call. Done here rather than at
  // mount: Monthly Subscription never needs it, a form opened and closed costs
  // nothing, and the amount field is still empty at this point so the round-trip
  // holds nothing up. func_recalc then reads _data and never fetches, which
  // matters because it fires on every keystroke in the amount field.
  if (!this.models?.['_data']?.flex_topup_rate) {
    let rate = 0;

    try {
      await this.runWorkflow(
        CREDIT_RELOAD_SAVE_WORKFLOW_ID,
        { data: { action: 'rate' } },
        (result) => {
          rate = parseFloat(result?.data?.flex_topup_rate) || 0;
        },
        (error) => {
          console.error('Credit Reload: Flex Topup Rate probe failed', error);
        }
      );
    } catch (error) {
      console.error('Credit Reload: Flex Topup Rate probe failed', error);
    }

    if (!rate) {
      this.$message.error(
        'Could not load the Flex Topup Rate - Add On credits cannot be priced.'
      );
    }

    // Merged, not assigned - _data is a shared scratch slot on the form instance.
    this.models['_data'] = { ...this.models['_data'], flex_topup_rate: rate };
  }

  this.triggerEvent('func_recalc');
})();

// Replace with the deployed workflow id.
const CREDIT_RELOAD_SAVE_WORKFLOW_ID = '2079099954205609985';

(async () => {
  try {
    this.showLoading('Saving Credit Reload...');

    const data = this.getValues();
    data.mode = 'form';

    await this.runWorkflow(
      CREDIT_RELOAD_SAVE_WORKFLOW_ID,
      { data },
      () => {
        this.$message.success(this.isEdit ? 'Update successfully' : 'Add successfully');
        this.hideLoading();

        if (this.parentGenerateForm) {
          this.parentGenerateForm.$refs.SuPageDialogRef.hide();
          this.parentGenerateForm.refresh();
        }
      },
      (error) => {
        this.hideLoading();
        console.error('Credit Reload save failed', error);
        this.$message.error(error?.data?.msg || 'An error occurred');
      },
    );
  } catch (error) {
    this.hideLoading();
    console.error('Credit Reload save failed', error);
    this.$message.error(error?.data?.msg || 'An error occurred');
  }
})();

